int checks=0;
void check(bool value,const char* message){++checks;if(!value)throw std::runtime_error(message);}
template<class T>T take(Outcome<T> value){if(!value.ok)throw std::runtime_error(value.error.original.code);return std::move(value.value);}
bool empty(const MilitaryActorOccupation& p){return p.custody_source_ids.empty()&&p.battle_source_ids.empty()&&p.siege_source_ids.empty();}
